    headers = {}
    allowed_origins = config.get('origins', ['*'])

    if '*' in allowed_origins:
        headers['Access-Control-Allow-Origin'] = '*'
    elif origin and origin in allowed_origins:
        headers['Access-Control-Allow-Origin'] = origin
    elif allowed_origins:
